import React from 'react';
import BGrid from 'react-bootstrap/lib/Grid';

import classNames from 'classnames';

export default class Grid extends React.Component {
  static propTypes = {
    fixed: React.PropTypes.bool,
    gutter: React.PropTypes.bool,
    collapse: React.PropTypes.bool,
    gutterTop: React.PropTypes.bool,
    gutterLeft: React.PropTypes.bool,
    gutterRight: React.PropTypes.bool,
    gutterBottom: React.PropTypes.bool,
  };

  render() {
    let fluid = true;

    if (this.props.fluid === false) {
      fluid = false;
    }

    if (this.props.fixed === true) {
      fluid = false;
    }

    let props = {
      ...this.props,
      fluid: fluid,
    };

    props.className = classNames(props.className, {
      'grid-gutter': props.gutter,
      'grid-collapse': props.collapse,
      'grid-gutter-top': props.gutterTop,
      'grid-gutter-left': props.gutterLeft,
      'grid-gutter-right': props.gutterRight,
      'grid-gutter-bottom': props.gutterBottom,
    });

    delete props.fixed;
    delete props.gutter;
    delete props.collapse;
    delete props.gutterTop;
    delete props.gutterLeft;
    delete props.gutterRight;
    delete props.gutterBottom;

    return <BGrid {...props} />
  }
}

Q:

Boundary Value Problem and FullSimplify

I'm confused about the output Mathematica is giving me when solving a boundary value problem of the form:
eq = ϵ y''[t] + 2 y'[t] + 2 y[t] == 0;
bc1 = y[0] == 0;
bc2 = y[1] == 1;

aSol = y[t] /. DSolve[{eq, bc1, bc2}, y[t], t][[1]][[1]]

This yields the correct answer, and produces plots like this for ep=1, ep=0.1, and ep=0.01.
Plot[{
  aSol /. ϵ -> 1,
  aSol /. ϵ -> 0.1,
  aSol /. ϵ -> 0.01},
 {t, 0, 1}, Frame -> True, FrameLabel -> {"t", "y(t)"}]


So far, so good!
However, if I simply ask Mathematica to FullSimplify[aSol], the resulting solution is no longer correct, and it does not satisfy one of the boundary conditions:
aSolSimpl = FullSimplify[aSol]

Plot[{
  aSol /. ϵ -> 0.05,
  aSolSimpl /. ϵ -> 0.05
  }, {t, 0, 1}, Frame -> True, FrameLabel -> {"t", "y(t)"}]

What's going wrong here?

A:

This behavior seems due to precision problems, as Henrik suggested in comments:
aSol = DSolveValue[{eq, bc1, bc2}, y[t], t];
aSolSimpl = FullSimplify[aSol];

Plot[Evaluate[aSol /. ϵ -> {1, 1/10, 1/100}], {t, 0, 1}]

Plot[
 Evaluate[aSolSimpl /. ϵ -> {1, 1/10, 1/100}], {t, 0, 1},
 WorkingPrecision -> $MachinePrecision
]

